        $w = (int) round($h * 354.64 / 63.53);

        return '<span class="bcp-logo">'
            . '<svg class="bcp-logo-mark" width="' . $w . '" height="'
            . $h . '" viewBox="0 0 354.64 63.53" fill="currentColor" '
